import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    def process(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                if v is not None:
                    new_dict[k] = process(v)
            return new_dict
        elif isinstance(obj, list):
            new_list = []
            for item in obj:
                if item is not None:
                    new_list.append(process(item))
            return new_list
        elif isinstance(obj, str):
            return re.sub(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b', REPLACE_NONE, obj)
        else:
            return obj

    def collect_values(obj, counter):
        if isinstance(obj, dict):
            for v in obj.values():
                collect_values(v, counter)
        elif isinstance(obj, list):
            for item in obj:
                collect_values(item, counter)
        else:
            counter[obj] += 1

    data = json.loads(json_str)
    processed = process(data)
    counter = Counter()
    collect_values(processed, counter)
    return {"data": processed, "value_counts": counter}

