import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("JSON data is malformed.")
    if not isinstance(data, list):
        raise ValueError("JSON data must be a list.")
    if len(data) == 0:
        raise ValueError("JSON data is empty.")
    records = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each entry must be a dictionary.")
        if "Country" not in item or "Population" not in item:
            raise ValueError("Missing required keys: 'Country' or 'Population'.")
        country = item["Country"]
        population = item["Population"]
        if not isinstance(country, str):
            raise ValueError("Country name must be a string.")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric.")
        if population < 0:
            raise ValueError("Population must be non-negative.")
        records.append({"Country": country, "Population": math.floor(population)})
    df = pd.DataFrame(records, columns=["Country", "Population"])
    output_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(output_path, index=False)
    except Exception:
        raise IOError("Cannot write to the specified directory.")
    return output_path, df

